let markdownPath = process.env.MARKDOWN_PATH;
let outputPath = process.env.OUTPUT_PATH;
const fs = require('fs');
if (!markdownPath) { throw new Error('Missing markdown_path'); }
if (!fs.existsSync(markdownPath)) { throw new Error('Markdown file not found'); }
if (!outputPath) { outputPath = markdownPath.replace(/\.md$/i, '.pdf'); }

const { execSync } = require('child_process');
try {
  execSync(`npx markdown-pdf "${markdownPath}" -o "${outputPath}"`);
  execResult = true;
} catch (e) {
